// ## Kaleidoscope script role: Custom block components (crops, bushes, trees, bark, planter).
// ============================================================================
// kaleidoscope_baking:plant   params from the block JSON (generated by tools/gen_content.py):
//   {max, chance, min_light, kind:"annual"|"perennial", harvest, harvest_min, harvest_max, reset, spread}
//   - random tick: grows one stage with `chance`% (needs light >= min_light)
//   - bone meal: +1..3 stages
//   - perennial + mature + interact: drops the harvest and falls back to stage `reset`
//   - annuals are harvested by breaking (stage-based loot tables)
//   - spread (mint): occasionally creeps onto adjacent grass
//   - series compat: may turn into the lead pack's plant (compat/index.js)
// kaleidoscope_baking:tree    sapling: grows 3 stages, then becomes a small tree
// kaleidoscope_baking:bark    cinnamon log: strip bark with a knife or axe; regrows slowly
// kaleidoscope_baking:herb_planter  pot for herb cuttings / strawberries (half speed)
// ============================================================================
import { BlockPermutation } from "@minecraft/server";
import { CONTENT } from "../data/generated/content.js";
import { maybeConvertPlant } from "../compat/index.js";
import {
  refuse, consumeHeld, heldItem, isCreative, itemName, mainhand, particle, safeBlock, sound, spawnItems, stackHasTag, t
} from "../utils/runtime.js";

const GROWTH = "kaleidoscope_baking:growth";
const STRIPPED = "kaleidoscope_baking:stripped";
const PLANT = "kaleidoscope_baking:plant";
const MSG = "kaleidoscope_baking.msg.planter.";
const centre = b => ({ x: b.x + 0.5, y: b.y + 0.5, z: b.z + 0.5 });
const randInt = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
const stageOf = b => { try { return Number(b.permutation.getState(GROWTH)) || 0; } catch { return 0; } };
const setStage = (b, s) => { try { b.setPermutation(b.permutation.withState(GROWTH, s)); } catch {} };

function light(block) {
  try { return block.above()?.getLightLevel?.() ?? block.getLightLevel?.() ?? 15; } catch { return 15; }
}

// Coffee grounds (1.1 by-product) work as a gentle fertiliser: always +1 stage.
const FERTILISERS = { "minecraft:bone_meal": () => randInt(1, 3), "kaleidoscope_baking:coffee_grounds": () => 1 };

function boneMeal(block, player, held, max, onMax) {
  const gain = FERTILISERS[held?.typeId];
  if (!gain) return false;
  const s = stageOf(block);
  if (s >= max && !onMax) return false;
  if (s >= max) onMax();
  else setStage(block, Math.min(max, s + (isCreative(player) ? max : gain())));
  consumeHeld(player, 1);
  sound(block.dimension, "item.bone_meal.use", centre(block));
  particle(block.dimension, "minecraft:crop_growth_emitter", centre(block));
  return true;
}

// ---------------------------------------------------------------------------
// Plant
// ---------------------------------------------------------------------------
const SPREAD_SOIL = new Set(["minecraft:grass_block", "minecraft:dirt", "minecraft:podzol"]);

function spread(block) {
  const [dx, dz] = [[1, 0], [-1, 0], [0, 1], [0, -1]][randInt(0, 3)];
  const target = safeBlock(block.dimension, { x: block.x + dx, y: block.y, z: block.z + dz });
  const below = safeBlock(block.dimension, { x: block.x + dx, y: block.y - 1, z: block.z + dz });
  if (!target || !below || !SPREAD_SOIL.has(below.typeId)) return;
  let air = false;
  try { air = target.isAir || target.typeId === "minecraft:short_grass"; } catch {}
  if (air) try { target.setPermutation(BlockPermutation.resolve(block.typeId, { [GROWTH]: 0 })); } catch {}
}

export const plantComponent = {
  onRandomTick({ block }, { params }) {
    if (maybeConvertPlant(block, GROWTH)) return;
    const s = stageOf(block);
    if (s < params.max) {
      if (light(block) >= (params.min_light ?? 0) && Math.random() * 100 < (params.chance ?? 10)) setStage(block, s + 1);
    } else if (params.spread && Math.random() < 0.05) spread(block);
  },
  onPlayerInteract({ block, player }, { params }) {
    if (!player) return;
    const held = heldItem(player);
    if (boneMeal(block, player, held, params.max)) return;
    if (params.kind !== "perennial" || stageOf(block) < params.max) return;
    spawnItems(block.dimension, centre(block), params.harvest, randInt(params.harvest_min ?? 1, params.harvest_max ?? 1));
    setStage(block, params.reset ?? 0);
    sound(block.dimension, "block.sweet_berry_bush.pick", centre(block));
  }
};

// ---------------------------------------------------------------------------
// Trees
// ---------------------------------------------------------------------------
const TREES = Object.fromEntries(CONTENT.trees.map(tr => [tr.id, tr]));
const REPLACEABLE = new Set(["minecraft:air", "minecraft:short_grass", "minecraft:tall_grass", "minecraft:fern", "minecraft:snow_layer"]);
const canReplace = b => { if (!b) return false; try { if (b.isAir) return true; } catch {} return REPLACEABLE.has(b.typeId); };

function logPerm(id) {
  try { return BlockPermutation.resolve(id, id.startsWith("minecraft:") ? { pillar_axis: "y" } : {}); } catch { return BlockPermutation.resolve(id); }
}

/** 4-block trunk with a rounded 2-layer crown. Gives up (keeps the sapling) if obstructed. */
export function growTree(block, tree) {
  const d = block.dimension, { x, y, z } = block;
  const height = 4;
  for (let i = 1; i <= height + 1; i++) if (!canReplace(safeBlock(d, { x, y: y + i, z }))) return false;
  const leaves = BlockPermutation.resolve(tree.leaves);
  for (let i = 0; i < height; i++) safeBlock(d, { x, y: y + i, z })?.setPermutation(logPerm(tree.log));
  for (const [dy, r] of [[height - 2, 2], [height - 1, 2], [height, 1], [height + 1, 0]]) {
    for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
      if (r === 2 && Math.abs(dx) === 2 && Math.abs(dz) === 2) continue;
      const b = safeBlock(d, { x: x + dx, y: y + dy, z: z + dz });
      if (canReplace(b)) try { b.setPermutation(leaves); } catch {}
    }
  }
  sound(d, "block.bamboo_sapling.place", centre(block));
  return true;
}

export const treeComponent = {
  onRandomTick({ block }, { params }) {
    const tree = TREES[params.tree];
    if (!tree || light(block) < 9) return;
    const s = stageOf(block);
    if (Math.random() > 0.12) return;
    if (s < 2) setStage(block, s + 1);
    else growTree(block, tree);
  },
  onPlayerInteract({ block, player }, { params }) {
    const tree = TREES[params.tree];
    if (player && tree) boneMeal(block, player, heldItem(player), 2, () => growTree(block, tree));
  }
};

// ---------------------------------------------------------------------------
// Cinnamon bark
// ---------------------------------------------------------------------------
export const barkComponent = {
  onPlayerInteract({ block, player }, { params }) {
    if (!player) return;
    const held = heldItem(player);
    if (!held || !(stackHasTag(held, "kaleidoscope_cookery:kitchen_knife") || stackHasTag(held, "minecraft:is_axe"))) return;
    let stripped = false;
    try { stripped = block.permutation.getState(STRIPPED) === true; } catch {}
    if (stripped) return;
    try { block.setPermutation(block.permutation.withState(STRIPPED, true)); } catch { return; }
    spawnItems(block.dimension, centre(block), params.bark, randInt(1, 2));
    sound(block.dimension, "use.wood", centre(block));
    damageHeld(player);
  },
  onRandomTick({ block }, { params }) {
    try {
      if (block.permutation.getState(STRIPPED) === true && Math.random() * 100 < (params.regrow_chance ?? 5))
        block.setPermutation(block.permutation.withState(STRIPPED, false));
    } catch {}
  }
};

function damageHeld(player) {
  if (isCreative(player)) return;
  const slot = mainhand(player);
  try {
    const s = slot.getItem();
    const dur = s?.getComponent("minecraft:durability");
    if (!dur) return;
    if (dur.damage + 1 >= dur.maxDurability) slot.setItem(undefined);
    else { dur.damage += 1; slot.setItem(s); }
  } catch {}
}

// ---------------------------------------------------------------------------
// Herb planter
// ---------------------------------------------------------------------------
const PLANTER = CONTENT.planter; // plant -> {seed, harvest, min, max}
const BY_SEED = Object.fromEntries(Object.entries(PLANTER).map(([p, v]) => [v.seed, p]));
const plantOf = b => { try { return b.permutation.getState(PLANT) ?? "none"; } catch { return "none"; } };

export const herbPlanterComponent = {
  onRandomTick({ block }) {
    const p = plantOf(block);
    if (p === "none") return;
    const s = stageOf(block);
    if (s < 3 && Math.random() < 0.06) setStage(block, s + 1);
  },
  onPlayerInteract({ block, player }) {
    if (!player) return;
    const held = heldItem(player);
    const p = plantOf(block);
    if (p === "none") {
      const plant = held && BY_SEED[held.typeId];
      if (!plant) { if (held) refuse(block.dimension, centre(block)); return; }
      try { block.setPermutation(block.permutation.withState(PLANT, plant).withState(GROWTH, 0)); } catch { return; }
      consumeHeld(player, 1);
      sound(block.dimension, "dig.grass", centre(block));
      return;
    }
    if (boneMeal(block, player, held, 3)) return;
    const s = stageOf(block);
    if (s >= 3) {
      const info = PLANTER[p];
      spawnItems(block.dimension, { x: block.x + 0.5, y: block.y + 0.8, z: block.z + 0.5 }, info.harvest, randInt(info.min, info.max));
      setStage(block, 1);
      sound(block.dimension, "block.sweet_berry_bush.pick", centre(block));
    } else if (!held && player.isSneaking) {
      spawnItems(block.dimension, centre(block), PLANTER[p].seed, 1);
      try { block.setPermutation(block.permutation.withState(PLANT, "none").withState(GROWTH, 0)); } catch {}
    }
  },
  onPlayerBreak({ block, brokenBlockPermutation }) {
    let p = "none";
    try { p = brokenBlockPermutation.getState(PLANT) ?? "none"; } catch {}
    if (p !== "none" && PLANTER[p]) spawnItems(block.dimension, centre(block), PLANTER[p].seed, 1);
  }
};
